% 自編牛頓法例題；以函數殘差停止，並非位置誤差
f = @(x) x.^2 - 2;
df = @(x) 2*x;
x0 = 1.5;
tolerance = 1e-12;
maxIterations = 50;
derivativeEpsilon = 1e-12; % 本教材的絕對門檻，並非通用尺度
validateattributes(x0, {'double'}, {'scalar','real','finite'});
validateattributes(tolerance, {'double'}, {'scalar','real','finite','positive'});
validateattributes(maxIterations, {'double'}, {'scalar','real','finite','integer','>=',1,'<=',1000});
x = x0;
fx = f(x);
if ~isreal(fx) || ~isfinite(fx)
    error('Newton:NonFinite', '初始函數值必須是有限實數。');
end
history = zeros(0,5); % 次數、更新前 x、f(x)、導數、x_next
converged = abs(fx) <= tolerance; % 初始值達標時為 0 次更新
fprintf(' k        x                 f(x)               df(x)              x_next\n');
for k = 1:maxIterations
    if converged
        break;
    end
    dfx = df(x);
    if ~isreal(dfx) || ~isfinite(dfx)
        error('Newton:NonFinite', '導數不是有限實數。');
    end
    if abs(dfx) <= derivativeEpsilon
        error('Newton:Derivative', '導數為零或接近零，停止更新。');
    end
    x_next = x - fx/dfx;
    if ~isreal(x_next) || ~isfinite(x_next)
        error('Newton:NonFinite', '下一次近似值不是有限實數。');
    end
    f_next = f(x_next);
    if ~isreal(f_next) || ~isfinite(f_next)
        error('Newton:NonFinite', '下一次函數值不是有限實數。');
    end
    history(end+1,:) = [k,x,fx,dfx,x_next];
    fprintf('%2d  %.16g  % .12e  %.16g  %.16g\n', k,x,fx,dfx,x_next);
    stalled = (x_next == x);
    x = x_next;
    fx = f_next;
    converged = abs(fx) <= tolerance;
    if converged
        break;
    end
    if stalled
        error('Newton:Precision', '浮點停滯，殘差尚未達標。');
    end
end
if ~converged
    error('Newton:MaxIterations', '尚未收斂至指定條件，已達迭代上限。');
end
fprintf('近似根 = %.16g；f(x) = %.12e；更新次數 = %d\n', x,fx,size(history,1));
% 達到殘差條件不直接保證位置精度，也不表示任意初始值均能收斂
